<script setup lang="ts">
import type { BusinessDetail } from '~/types/business'
import type { BusinessEditorInitial } from '~/composables/useBusinessDraft'
import type { PurchaseReturnPayload } from '~/types/purchase-return'
import { validateBusinessDraft } from '~/utils/business'
const props = defineProps<{ identity: string; initial: BusinessEditorInitial<PurchaseReturnPayload>; refresh: () => Promise<BusinessDetail | null> }>()
const { payload, status, issues, preview, busy, failure, notice, storageFailure, created, pending, dirty, locked, canRetry, canReview, send, showPreview, review, resetNew, synchronizeTerminal } = useBusinessDraft(props.identity, props.initial, props.refresh)
watch(() => props.initial, synchronizeTerminal, { immediate: true })
const connection = useConnection(), available = computed(() => connection.value === 'connected')
const errors = ref<Record<string, string>>({}), form = ref<HTMLFormElement | null>(null), previewPanel = ref<HTMLElement | null>(null), archiveReview = ref(false)
const fieldErrors = computed(() => ({ ...Object.fromEntries(issues.value.map(item => [item.field.replace(/^data\./, ''), item.message])), ...errors.value }))
async function focusIssue() { await nextTick(); const name = Object.keys(fieldErrors.value)[0]; const target = name ? form.value?.querySelector<HTMLElement>(`[data-field="${name}"]`) : null; if (target) target.focus(); else previewPanel.value?.focus() }
async function saveDraft() { errors.value = validateBusinessDraft(payload.value); if (Object.keys(errors.value).length) { await focusIssue(); return }; await send(props.initial.recordId ? 'revise' : 'create') }
async function previewDraft() { if (await showPreview()) { await nextTick(); previewPanel.value?.focus() } else await focusIssue() }
async function startNew() { resetNew(); await nextTick(); form.value?.querySelector<HTMLElement>('select')?.focus() }
</script>
<template>
  <section class="business-editor purchase-return-editor" aria-label="구입 반품 초안 입력" :aria-busy="busy">
    <p v-if="storageFailure" class="notice warning" role="alert">{{ storageFailure }}</p><div v-if="failure" class="notice warning" role="alert"><p>{{ failure }}</p><button v-if="canReview" class="text-button" type="button" :disabled="busy || !available" @click="review">최신 기록 확인 후 입력 검토</button></div><p v-if="pending && !failure" class="notice warning" role="status">{{ busy ? '처리 결과를 확인하고 있습니다.' : '완료를 확인하지 못한 요청이 있습니다. 같은 요청으로 재시도해 주세요.' }}</p><button v-if="canRetry && !busy" class="secondary-button" type="button" :disabled="!available" @click="send(pending!.action)">같은 업무 요청 재시도</button><p v-if="notice" class="notice success" role="status">{{ notice }}</p><NuxtLink v-if="created" class="business-saved-link" :to="`/business/${created.id}`">저장한 초안 열기</NuxtLink><button v-if="created" class="text-button" type="button" :disabled="busy" @click="startNew">새 구입 반품 초안 작성</button>
    <section v-if="status !== 'draft' && dirty" class="notice warning"><h2>이 화면에 남은 미저장 입력</h2><p>다른 화면에서 확정하거나 보관해 이 입력은 반영되지 않았습니다.</p><p>{{ payload.data.quantity || '수량 미입력' }}{{ payload.data.unit }} · 원입고 {{ payload.data.receipt_id }}</p><p class="preserve-lines">{{ payload.data.note }}</p></section>
    <form v-if="status === 'draft' && !created" ref="form" novalidate @submit.prevent="saveDraft"><div class="section-heading"><h2>구입 반품 초안</h2><p>원입고와 실제 반품 수량을 확인하세요. 현재 평균 가치로 차감합니다.</p></div><PurchaseReturnFields v-model="payload.data" :disabled="locked || !available" :errors="fieldErrors"/><p v-if="dirty" class="draft-note" role="status">화면에서 바꾼 내용이 아직 임시 저장되지 않았습니다.</p><div class="button-row"><button class="primary-button" type="submit" :disabled="locked || !available">{{ initial.recordId ? '수정 내용 임시 저장' : '초안 임시 저장' }}</button><button v-if="initial.recordId" class="secondary-button" type="button" :disabled="locked || !available || dirty" @click="previewDraft">확정 전 미리보기</button></div><p class="field-hint">미완성 입력도 임시 저장할 수 있습니다. 미확인 수량이나 가치를 0으로 채우지 않습니다.</p></form>
    <section v-if="preview" ref="previewPanel" class="business-preview purchase-return-preview" tabindex="-1" aria-labelledby="purchase-return-preview-title"><h2 id="purchase-return-preview-title">구입 반품 미리보기</h2><ul v-if="preview.issues.length" class="business-issues"><li v-for="item in preview.issues" :key="`${item.field}-${item.code}`">{{ item.message }}</li></ul><PurchaseReturnResult v-if="preview.effect?.kind === 'purchase_return'" :value="preview.effect.purchase_return"/><p v-if="!preview.can_confirm" class="field-hint">입력을 유지했습니다. 원입고 한도와 보유 근거를 확인한 뒤 다시 미리보기해 주세요.</p><button class="primary-button" type="button" :disabled="!available || busy || !!pending || dirty || !preview.can_confirm" @click="send('confirm')">이 내용으로 확정</button></section>
    <section v-if="initial.recordId && status === 'draft'" class="archive-section"><button v-if="!archiveReview" class="text-button" type="button" :disabled="locked || !available" @click="archiveReview = true">초안 보관</button><div v-else class="notice warning"><p>화면의 미저장 입력은 함께 저장되지 않습니다. 확정된 기록은 바뀌지 않습니다.</p><div class="button-row"><button class="secondary-button" type="button" :disabled="locked || !available" @click="send('archive')">초안 보관 확정</button><button class="text-button" type="button" :disabled="locked" @click="archiveReview = false">취소</button></div></div></section>
  </section>
</template>
